from collections import deque

def get_moves(r, c, piece, N):
    moves = []
    if piece == 0:  # knight
        for dr, dc in [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                moves.append((nr, nc))
    elif piece == 1:  # bishop
        for dr, dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
            nr, nc = r+dr, c+dc
            while 0 <= nr < N and 0 <= nc < N:
                moves.append((nr, nc))
                nr += dr; nc += dc
    else:  # rook
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            while 0 <= nr < N and 0 <= nc < N:
                moves.append((nr, nc))
                nr += dr; nc += dc
    return moves
